"use client";

import type { InputHTMLAttributes, ReactNode } from "react";
import "./styles/skeuo-checkbox.css";

export type SkeuoCheckboxProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "type" | "checked" | "defaultChecked" | "onChange"
> & {
  label: ReactNode;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
};

export function SkeuoCheckbox({
  label, checked, onCheckedChange, className = "", ...props
}: SkeuoCheckboxProps) {
  return (
    <label data-sk-root="" className={`sk-checkbox ${className}`.trim()}>
      <input
        {...props}
        type="checkbox"
        data-sk-selection-sound="checkbox"
        checked={checked}
        onChange={(event) => onCheckedChange(event.currentTarget.checked)}
      />
      <span className="sk-checkbox-housing" aria-hidden="true">
        <span className="sk-checkbox-well" />
        <span className="sk-checkbox-axle" />
        <span className="sk-checkbox-tile">
          <span className="sk-checkbox-face"><span className="sk-checkbox-dash" /></span>
          <span className="sk-checkbox-face sk-checkbox-checked-face">
            <svg viewBox="0 0 16 16" fill="none" focusable="false">
              <path d="m3.5 8 3 3 6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </span>
        </span>
      </span>
      <span className="sk-checkbox-label">{label}</span>
    </label>
  );
}

@import "./skeuo-base.css";

:where(.light, [data-theme="light"]) { --sk-checkbox-scheme: light; }
:where(.dark, [data-theme="dark"]) { --sk-checkbox-scheme: dark; }

.sk-checkbox {
  --sk-checkbox-size: 38px;
  color-scheme: var(--sk-checkbox-scheme, light dark);
  display: flex;
  align-items: center;
  position: relative;
  min-block-size: 48px;
  gap: 12px;
  cursor: pointer;
}
.sk-checkbox:has(input:disabled) { opacity: .45; cursor: not-allowed; }
.sk-checkbox > input { position: absolute; inline-size: 1px; block-size: 1px; opacity: 0; margin: 0; }
.sk-checkbox-label { min-inline-size: 0; overflow-wrap: anywhere; }
.sk-checkbox-housing {
  position: relative;
  flex: none;
  inline-size: var(--sk-checkbox-size);
  block-size: var(--sk-checkbox-size);
  perspective: 120px;
  border: 1px solid #394a3d;
  border-radius: calc(var(--sk-checkbox-size) * .237);
  background: linear-gradient(140deg, light-dark(#a5b4a0, #718578),
    light-dark(#637b68, #3f5448) 36%, light-dark(#3a4e40, #25352d));
  box-shadow: inset 0 1px #f6ffedbd, inset 1px 0 #d9e7ce69, inset 0 -2px 2px #15251eb3,
    0 2px #33463a, 0 3px #203329, 0 5px 7px #14241959;
}
.sk-checkbox-well {
  position: absolute;
  inset: 8%;
  border: 1px solid #243a2d;
  border-radius: calc(var(--sk-checkbox-size) * .184);
  background: linear-gradient(#14271c, #2a4032 63%, #4b6250);
  box-shadow: inset 0 3px 5px #07110ae6, inset 2px 0 3px #07110a99, 0 1px #c5d4bb55;
}
.sk-checkbox > input:focus-visible + .sk-checkbox-housing { outline: 2px solid var(--sk-ring); outline-offset: 3px; }
.sk-checkbox-axle {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}
.sk-checkbox-axle::before, .sk-checkbox-axle::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inline-size: 14%;
  block-size: 22%;
  transform: translateY(-50%);
  border: 1px solid #645c4f;
  border-radius: 2px;
  background: linear-gradient(#f5ebd6, #c1b49c 35%, #736957);
  box-shadow: inset 0 1px #fff6d99e, 0 1px 2px #10180ed9;
}
.sk-checkbox-axle::before { inset-inline-start: 0; }
.sk-checkbox-axle::after { inset-inline-end: 0; }
.sk-checkbox-tile {
  --sk-checkbox-press: 0px;
  --sk-checkbox-turn: 0deg;
  position: absolute;
  inset: 14%;
  transform: translateY(var(--sk-checkbox-press)) rotateX(var(--sk-checkbox-turn));
  transform-style: preserve-3d;
  transition: transform 320ms cubic-bezier(.32, 0, .22, 1);
}
.sk-checkbox:active:not(:has(input:disabled)) .sk-checkbox-tile { --sk-checkbox-press: 1.5px; }
.sk-checkbox > input:checked ~ .sk-checkbox-housing .sk-checkbox-tile { --sk-checkbox-turn: 180deg; }
.sk-checkbox-face {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border: 1px solid light-dark(#807766, #4b4e49);
  border-radius: calc(var(--sk-checkbox-size) * .132);
  color: light-dark(#6a5c49, var(--sk-muted));
  background: linear-gradient(145deg, #ffffff55, #ffffff0c 42%, #00000030),
    light-dark(#eee4d3, var(--sk-surface-raised));
  box-shadow: inset 0 1px #ffffff8c, inset 1px 0 #ffffff36, inset 0 -2px #0004,
    0 2px light-dark(#81735d, #111714), 1px 2px 3px #08120ccd;
  backface-visibility: hidden;
}
.sk-checkbox-checked-face {
  transform: rotateX(180deg);
  border-color: #14291e;
  color: var(--sk-accent-ink);
  background: linear-gradient(145deg, #ffffff55, #ffffff0c 42%, #00000030), var(--sk-accent);
  box-shadow: inset 0 1px #ffffff8c, inset 1px 0 #ffffff36, inset 0 -2px #0004,
    0 2px #182f23, 1px 2px 3px #08120ccd;
}
.sk-checkbox-dash {
  inline-size: 42%;
  block-size: 2px;
  border-radius: 1px;
  background: currentColor;
  box-shadow: inset 0 1px #30271b7a, 0 1px #ffffff8c;
}
.sk-checkbox-checked-face svg { inline-size: 67%; block-size: auto; }

@media (prefers-reduced-motion: reduce) {
  .sk-checkbox-tile { transition: none; }
}
@media (forced-colors: active) {
  .sk-checkbox > input { position: static; inline-size: 1.25rem; block-size: 1.25rem; opacity: 1; }
  .sk-checkbox-housing { display: none; }
}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
